import {actions} from './actions.js';
import {dayKey} from './store.js';
import {pillars,cosmetics,achievements} from './game-data.js';
import {balances,playerLevel,pillarState,dailyClear,streak,activityDates,comeback,bossProgress,transformationSummary,weeklyGameSummary,nextCelebration} from './game.js';
import {equipmentAllows,currentLevel} from './training.js';
import {availableWindow} from './schedule.js';
export function createGameUI(ctx){const d=()=>ctx.data(),e=ctx.esc;let trophySort='date',trophyCategory='All';const profile=()=>d().gameProfile.find(p=>p.id==='player')||{title:'The Beginner',favorites:[],equipped:{orb:'core'}};
 const level=()=>playerLevel(balances(d()).xp,d().gameConfigurations[0]);
 function pillarCard(){const state=pillarState(d(),dayKey()),count=state.filter(p=>p.completion).length;return `<article class="card wide pillar-card"><div class="card-head"><div><span class="eyebrow">TODAY'S PILLARS</span><h2>${count} / ${state.filter(p=>p.planned).length} planned exposures</h2></div><button data-action="pillarPlan">Plan my day</button></div><div class="pillar-grid">${state.map(p=>`<div class="pillar ${p.completion?'complete':''}"><span class="pillar-symbol">${p.icon}</span><strong>${e(p.name)}</strong><small>${p.completion?'★ Honored':p.planned?e(p.mode):'Rest / not planned'}</small>${p.planned?`<button data-action="pillarStart" data-pillar="${p.id}" ${p.completion?'disabled':''}>${p.completion?'Recorded':'Open exposure'}</button>`:''}</div>`).join('')}</div><p class="legend">${dailyClear(d(),dayKey())?'Day cleared · your planned requirements are honored.':count===4?'Quad Clear · light versions count, too.':'Useful exposure counts. An unfinished day never removes progress.'} Player XP never substitutes for physical proof.</p></article>`}
 function todayCard(){const l=level(),back=comeback(d(),dayKey()),recent=d().gameCelebrations.filter(c=>!c.seen);return pillarCard()+`<article class="card"><div class="card-head"><h2>${back.gap>0?'Welcome back.':'Your orbit'}</h2><button data-action="gameRewards">What did I earn?</button></div><h3>Level ${l.level} · ${e(profile().title)}</h3>${ctx.progress(l.percent,'Player level')}<p class="muted">${l.remaining} XP to the next engagement level.</p>${back.gap>0?`<p class="legend">${back.lastWorkout?'Last workout: '+e(back.lastWorkout.name)+' · '+back.lastWorkout.date: 'Your recorded progress stays with you.'} A light exposure is a good way to restart.</p>`:''}${recent.length?`<button data-action="gameCelebrations">${recent.length} new milestone${recent.length===1?'':'s'} ↗</button>`:''}<p class="legend">Your titles, records and mastery remain yours through missed days.</p></article>`}
 function questPage(){const date=dayKey(),quests=d().gameQuests.filter(q=>q.date<=date&&q.deadline>=date&&q.status!=='archived').sort((a,b)=>a.priority-b.priority),bosses=bossProgress(d(),date);return ctx.heading('Your next chapter.','Earned through useful action. Physical capability stays grounded in proof.',`<button data-action="trophyRoom">Trophy Room ↗</button>`)+`<div class="grid">${pillarCard()}<article class="card wide"><div class="card-head"><h2>Quests in your orbit</h2><button data-action="questCreate">+ Personal quest</button></div>${quests.map(q=>`<div class="row"><div class="row-main"><h3>${q.status==='completed'?'✓ ':''}${e(q.name)}</h3><p>${e(q.type)} · about ${q.minutes} min · ${e(q.effort)}${q.optional?' · optional':''}</p></div><button data-action="questDetail" data-id="${q.id}">${q.status==='completed'?'Evidence':'Details / next step'}</button></div>`).join('')||'<p class="empty">Your next useful quests appear from your plan and unfinished goals.</p>'}</article><article class="card wide"><h2>Road to Gravity I</h2><div class="chain">${bosses.find(b=>b.id==='gravity').steps.map((s,i)=>`<div><small>STEP ${i+1}</small><strong>${s.proven?'✓':'○'} ${e(s.name)}</strong></div>`).join('')}</div><p class="legend">Each step keeps its own evidence. Earned XP cannot skip a prerequisite.</p><button data-route="Dominance">Practice the path ↗</button></article>${bosses.map(b=>`<article class="card"><span class="eyebrow">BOSS TRIAL</span><h2 style="margin-top:14px">${e(b.name)}</h2><p class="muted">${e(b.description)}</p>${ctx.progress(b.percent,b.name)}<p>${b.cleared?'★ Cleared · '+b.cleared.date:b.steps.filter(s=>s.proven).length+' / '+b.steps.length+' evidence steps proved'}</p><button data-action="bossDetail" data-id="${b.id}">${b.cleared?'Relive the clear':'Path / requirements'}</button></article>`).join('')}<article class="card wide"><h2>Balance belongs here.</h2><p>Personal Time is a real commitment. Protecting it does not create a relationship score, duration rewards or streak pressure.</p><button data-action="planner">Open Planner</button></article></div>`}
 function profileCard(){const l=level(),p=profile(),week=weeklyGameSummary(d(),dayKey()),boss=d().bossClears.slice().sort((a,b)=>b.at.localeCompare(a.at))[0],s=streak(activityDates(d()),dayKey());return `<article class="card wide profile-showcase"><span class="eyebrow">PLAYER SHOWCASE</span><h2>${e(p.title)}</h2><p>Level ${l.level} · ${balances(d()).xp} earned XP · ${balances(d()).coins} available coins</p><div class="favorite-badges">${p.favorites.map(id=>`<button data-action="badgeDetail" data-id="${id}">★ ${e(d().gameBadges.find(b=>b.id===id)?.name)}</button>`).join('')}</div><p class="legend">${boss?'Most recent boss: '+e(boss.name)+' · '+boss.date:'Your first boss clear is ahead.'}</p><details style="margin:16px 0"><summary>Current mastery focus</summary>${d().skillDefinitions.filter(s=>['pull','curl','carry'].includes(s.id)).map(s=>`<p>${e(s.name)} · ${e(currentLevel(s,d()).name)}</p>`).join('')}</details><div class="actions"><button data-action="trophyRoom">Trophy Room</button><button data-action="gameWardrobe">Titles / cosmetics</button><button data-action="gameRewards">Reward ledger</button></div></article><article class="card wide"><div class="card-head"><h2>Week complete / so far</h2><button data-action="gameWeek">Full review</button></div><div class="metrics">${[[week.xp,'XP earned'],['+'+week.coins,'Coins earned'],[week.mastery,'Mastery clears'],[week.prs,'Improved PRs'],[week.quad,'Quad Clear days'],[week.personal,'Protected personal-time blocks']].map(([v,label])=>`<div class="metric"><strong>${v}</strong><small>${label}</small></div>`).join('')}</div><p class="legend">Active-day streak ${s.current} · personal best ${s.best}. A break changes the count only.</p></article>`}
 function evidenceHTML(evidence){return `<details open><summary>Linked evidence</summary>${(Array.isArray(evidence)?evidence:[evidence]).map(v=>`<p class="legend">${e(({sessions:'Workout',masteryAwards:'Mastery proof',checkins:'Check-in',recordEvents:'Personal record',dailyStates:'Daily plan',gameQuests:'Quest',rewardLedger:'Reward',events:'Protected commitment',attempts:'Trial evidence',gameBadges:'Earned badge',bossClears:'Boss clear'}[v.store])||v.stat||'Record')} · ${e(v.id||v.value||'recorded')} ${v.setId?'· set '+e(v.setId):''}${v.store==='sessions'?` <button data-action="session" data-id="${e(v.id)}">Open session</button>`:''}</p>`).join('')}</details>`}
 function trophyRoom(){const items=d().gameBadges.filter(b=>trophyCategory==='All'||b.category===trophyCategory);items.sort((a,b)=>trophySort==='rarity'?['Legendary','Epic','Rare','Uncommon','Common'].indexOf(a.rarity)-['Legendary','Epic','Rare','Uncommon','Common'].indexOf(b.rarity):trophySort==='category'?a.category.localeCompare(b.category):b.at.localeCompare(a.at));ctx.modal('Trophy Room',`<div class="fields"><label class="field">Sort<select data-game-sort>${['date','rarity','category'].map(s=>`<option ${s===trophySort?'selected':''}>${s}</option>`).join('')}</select></label><label class="field">Category<select data-game-category>${['All','Boss','Dominance','PR','Secret','Transformation','Sport','Consistency','Recovery','Milestone'].map(s=>`<option ${s===trophyCategory?'selected':''}>${s}</option>`).join('')}</select></label></div>${items.map(b=>`<div class="row"><div class="row-main"><h3>★ ${e(b.name)}</h3><p>${e(b.category)} · ${e(b.rarity)} · ${b.date}</p></div><button data-action="badgeDetail" data-id="${b.id}">Open</button></div>`).join('')||'<p class="empty">No earned trophies in this section yet.</p>'}<details><summary>Unrevealed signals</summary><p class="legend">${achievements.filter(a=>a.secret&&!d().gameBadges.some(b=>b.id===a.id)).length} hidden achievements await real progress. Their requirements stay hidden until earned.</p></details>`);document.querySelector('[data-game-sort]').onchange=event=>{trophySort=event.target.value;trophyRoom()};document.querySelector('[data-game-category]').onchange=event=>{trophyCategory=event.target.value;trophyRoom()}}
 function badgeDetail(id){const b=d().gameBadges.find(b=>b.id===id);if(!b)return;ctx.modal(b.name,`<span class="eyebrow">${e(b.category)} · ${e(b.rarity)}</span><p>${e(b.description)}</p><p>Earned ${b.date} · ${b.reward.xp} XP · ${b.reward.coins} coins</p>${b.title?`<p>Title unlocked: ${e(b.title)}</p>`:''}${evidenceHTML(b.evidence)}<button data-action="favoriteBadge" data-id="${b.id}">${profile().favorites.includes(b.id)?'Remove from showcase':'Showcase this badge'}</button>`)}
 function bossDetail(id){const b=bossProgress(d(),dayKey()).find(b=>b.id===id);if(!b)return;const clear=b.cleared;ctx.modal(clear?'Boss cleared // '+b.name:b.name,`<div class="boss-moment"><span class="boss-orbit">◇</span><span class="eyebrow">${clear?'BOSS CLEARED':'MAJOR MILESTONE'}</span><h2>${e(b.name)}</h2><p>${e(b.description)}</p>${clear?.quote?`<p class="boss-quote">“${e(clear.quote)}”</p>`:''}</div>${clear?`<p>${clear.date} · +${clear.reward.xp} XP · +${clear.reward.coins} coins</p><p>Title: ${e(clear.title)} · ${e(clear.rarity)} badge</p>${evidenceHTML(clear.evidence)}<details><summary>Important stats</summary>${Object.entries(clear.stats).map(([key,value])=>`<p>${e(key.replace(/([A-Z])/g,' $1'))}: ${Array.isArray(value)?value.map(v=>typeof v==='object'?e(v.name?`${v.proven?'✓':'○'} ${v.name}`:`${v.type}: ${v.value} ${v.unit}`):e(v)).join('<br>'):e(value??'Not logged')}</p>`).join('')}</details>`:b.steps.map(s=>`<p>${s.proven?'✓':'○'} ${e(s.name)}</p>`).join('')+'<p class="legend">Boss rewards are granted once from recorded evidence.</p>'}`)}
 function rewards(){const l=level();ctx.modal('What you earned',`<h3>Level ${l.level} · ${l.remaining} XP to next level</h3><p>${balances(d()).xp} XP · ${balances(d()).coins} available coins</p><p class="legend">Session rewards are capped at ${d().gameConfigurations[0].sessionDailyLimit} useful sessions a day. Repeated water logs and relationship duration grant no XP. Mastery stays independent of this ledger.</p>${d().rewardLedger.slice().sort((a,b)=>b.at.localeCompare(a.at)).slice(0,60).map(r=>`<details style="margin:14px 0"><summary>${r.amount?'+ '+r.amount+' XP · ':''}${r.coins?r.coins+' coins · ':''}${e(r.reason)}</summary><p>${r.date} · source ${e(r.id)}</p>${evidenceHTML(r.evidence)}</details>`).join('')}`)}
 function wardrobe(){const p=profile();ctx.modal('Titles & cosmetic orbit',`<h3>One title. Your choice.</h3>${d().gameInventory.filter(i=>i.type==='title').map(i=>`<div class="row"><strong>${e(i.name)}</strong><button data-action="equipGame" data-type="title" data-id="${e(i.itemId)}">${p.title===i.itemId?'Equipped':'Equip'}</button></div>`).join('')}<h3 style="margin-top:26px">Cosmetics · ${balances(d()).coins} coins</h3>${cosmetics.map(c=>{const owned=d().gameInventory.some(i=>i.id==='cosmetic:'+c.id);return `<div class="row"><div class="row-main"><h3>${e(c.name)}</h3><p>${c.slot} · ${c.cost} coins</p></div><button data-action="${owned?'equipGame':'buyCosmetic'}" data-type="cosmetic" data-id="${c.id}">${p.equipped[c.slot]===c.id?'Equipped':owned?'Equip':'Unlock'}</button></div>`}).join('')}<p class="legend">Cosmetics change appearance only. Coins cannot buy a skill, workout completion or physical progress.</p>`)}
 function planDialog(){const date=dayKey(),current=d().pillarPlans.find(p=>p.id===date);ctx.modal('Plan your exposures',`<form class="fields">${ctx.field('Plan date','date','date',date,'required min="'+date+'"')}<p class="legend">Choose planned exposures, including light or recovery versions. Today’s plan is preserved once an exposure is recorded.</p>${pillars.map(p=>{const item=current?.items.find(i=>i.id===p.id);return `<label><input type="checkbox" name="planned:${p.id}" ${item?.planned!==false?'checked':''}> ${e(p.name)}</label><label class="field">${e(p.name)} mode<select name="mode:${p.id}">${['Normal','Light / Rebuild','Recovery'].map(m=>`<option ${m===(item?.mode||'Normal')?'selected':''}>${m}</option>`).join('')}</select></label>`}).join('')}<label><input type="checkbox" name="water" ${current?.requireWater?'checked':''}> Include my water target in Day Clear</label><button class="white">Save plan</button></form>`,async f=>{await actions.dispatch('savePillarPlan',{date:f.get('date'),items:pillars.map(p=>({id:p.id,planned:f.has('planned:'+p.id),mode:f.get('mode:'+p.id)})),requireWater:f.has('water')});ctx.toast('Plan saved. Rest is a valid choice.')})}
 async function pillarStart(id){const p=pillarState(d(),dayKey()).find(p=>p.id===id);if(!p?.planned||p.completion)return;const context=d().equipmentProfiles.find(x=>x.id===ctx.pref().equipmentContext)||d().equipmentProfiles[0];const targets={body:['wall-pushup','supported-hang','scapular'],mobility:['supported-squat','mobility'],strength:['curl','squat','hip-hinge'],movement:['walk']};const ex=targets[id].map(key=>d().exercises.find(x=>x.id===key)).find(x=>x&&equipmentAllows(x,context));if(!ex)return ctx.toast('Choose equipment or a suitable movement first.');const light=p.mode!=='Normal';const movement={exerciseId:ex.id,name:ex.name,sets:id==='movement'?1:light?1:2,reps:light?5:8,weight:ex.resistance==='weighted'&&!light?5:0,durationSeconds:ex.measurement==='duration'?15:0,distanceMeters:id==='movement'?light?200:500:0,restSeconds:60,difficultyTarget:light?4:6};ctx.modal(p.name+' / planned exposure',`<p>${e(ex.name)} · ${e(p.mode)} · about ${p.minutes} minutes</p><p class="legend">${e(availableWindow(d().events).reason)} This opens a session; it does not automatically reserve time over protected commitments.</p><button class="white" data-action="beginPillar" data-pillar="${id}">Begin exposure</button>`);document.querySelector('[data-action="beginPillar"]').onclick=async()=>{try{const s=await actions.dispatch('startSession',{kind:'Extra',name:p.name+' / '+p.mode,exercises:[movement],mode:p.mode,pillarId:id});await ctx.refresh();ctx.showSession(s.id)}catch(error){ctx.toast(error.message)}}}
 function questDetail(id){const q=d().gameQuests.find(q=>q.id===id);if(!q)return;const action=q.condition==='trial'?`<button data-action="proofStart" data-skill="${q.skill}" data-level="${q.levelId}" data-trial="${q.trialId}">Practice requirement</button>`:q.condition==='pillar'?`<button data-action="pillarStart" data-pillar="${q.pillarId}">Open exposure</button>`:q.condition==='boss'?`<button data-action="bossDetail" data-id="${q.bossId}">Open boss path</button>`:q.condition==='recovery'?'<button data-action="extraMuscle" data-muscle="Recovery">Choose recovery work</button>':q.condition==='transformation-checkin'?'<button data-action="checkin">Log weekly check-in</button>':q.condition==='extra'?'<button data-action="hungry">Useful optional training</button>':q.condition==='personal'?`<button data-action="personalQuestComplete" data-id="${q.id}">Record deliberate completion</button>`:'<button data-route="Today">Open today</button>';ctx.modal(q.name,`<span class="eyebrow">${e(q.type)} · ${e(q.status)}</span><p>${e(q.description||'Useful progress, grounded in your plan.')}</p><p>About ${q.minutes} minutes · priority ${q.priority} · ${e(q.effort)} · deadline ${q.deadline}</p><p>${q.status==='completed'?'Recorded quest reward':'Possible quest reward'}: ${q.status==='completed'?(d().rewardLedger.find(r=>r.id==='quest:'+q.id)?.amount||0):q.reward.xp} XP · ${q.status==='completed'?(d().rewardLedger.find(r=>r.id==='quest:'+q.id)?.coins||0):q.reward.coins} coins${q.type==='Daily'?' · exposure rewards appear in the ledger':''}</p>${q.condition==='weekly'?`<p>${q.progress||0} / ${q.target} · optional, light work counts.</p>`:''}${q.status==='completed'?evidenceHTML(q.evidence):action}`)}
 function weekReview(){const w=weeklyGameSummary(d(),dayKey()),t=transformationSummary(d(),dayKey());ctx.modal('Your week, recorded',`<div class="metrics">${[[w.xp,'XP'],['+'+w.coins,'Coins earned'],[w.mastery,'Mastery clears'],[w.prs,'PR improvements'],[w.quad,'Four Pillars days'],[w.personal,'Protected personal-time blocks']].map(([v,k])=>`<div class="metric"><strong>${v}</strong><small>${k}</small></div>`).join('')}</div><h3>Boss paths</h3>${bossProgress(d(),dayKey()).filter(b=>!b.cleared).map(b=>`<p>${e(b.name)} · ${b.steps.filter(s=>s.proven).length}/${b.steps.length} evidence steps</p>`).join('')}<h3>Consistency, without penalties</h3>${['active','routine','training','mobility','walking'].map(type=>{const s=streak(activityDates(d(),type),dayKey());return `<p>${type}: ${s.current} current · ${s.best} personal best</p>`}).join('')}<h3>Transformation</h3><p>${Math.floor(t.elapsed/7)} / ${t.config.durationWeeks} weeks elapsed · ${t.checkins.length} check-ins</p><p>${t.weight.enough?'Logged weight trend: '+t.weight.recent.toFixed(1)+' lb':'More dated measurements are needed for a reliable trend.'}</p><p class="legend">Body changes are individual. Consistency and capability count alongside measurements.</p>`)}
 function celebrations(){const items=d().gameCelebrations.filter(c=>!c.seen);ctx.modal('Milestones in your orbit',items.map(c=>`<div class="row"><div class="row-main"><h3>${e(c.name)}</h3><p>${c.date} · ${c.type}</p></div><button data-action="${c.type==='boss'?'bossDetail':c.type==='badge'?'badgeDetail':'gameRewards'}" data-id="${e(c.evidence[0]?.id||'')}">Open</button><button data-action="ackCelebration" data-id="${c.id}">Seen</button></div>`).join('')||'<p>All caught up. Every milestone remains accessible in the Trophy Room.</p>')}
 async function maybeCelebrate(){if(d().sessions.some(s=>['active','paused'].includes(s.status)&&!s.supersededBy))return;const intensity=ctx.pref().celebrationIntensity||(ctx.pref().celebrations===false?'Off':'Minimal');const next=nextCelebration(d(),ctx.pref());if(!next||intensity==='Off')return;await actions.dispatch('acknowledgeCelebration',{id:next.id});next.seen=true;if(intensity==='Full'&&next.type==='boss')bossDetail(next.evidence[0].id);else ctx.toast(next.name+' · saved in your Trophy Room')}
 function command(text){const t=text.toLowerCase(),memory=ctx.pref().memory;const restrictedBadge=b=>b.category==='Transformation'&&!memory.metrics||b.id==='balance'&&!memory.schedule||b.id==='respect-recovery'&&!memory.metrics;const recognized=/quests|trophy|badge|boss|xp|four pillars|all four|accomplish.*week|what.*earn|what.*unlock|what.*level|minutes/.test(t);if(!recognized)return false;if(!memory.training||!memory.goals){ctx.modal('Caelum / memory controls','<p>Enable Training and Goals access to use game progression records.</p>');return true}if(/until.*next|xp.*until|what.*level/.test(t)){const l=level();ctx.modal('Your player level',`<h3>Level ${l.level}</h3><p>${balances(d()).xp} earned XP · ${l.remaining} XP until the next engagement level.</p><p class="legend">Player Level does not unlock physical skills.</p>`)}else if(/what.*unlock/.test(t)&&!/closest/.test(t)){ctx.modal('Your cosmetic unlocks',d().gameInventory.map(i=>`<p>${e(i.type)} · ${e(i.name)}</p>`).join('')+'<p>Physical unlocks remain in your evidence-driven Dominance paths.</p>')}else if(/trophy/.test(t)){if(d().gameBadges.some(restrictedBadge)){ctx.modal('Caelum / memory controls','<p>Enable the relevant Health Metrics and Schedule access for a full trophy review. You can open the Trophy Room directly in Profile.</p>')}else trophyRoom()}else if(/badge/.test(t)){const b=d().gameBadges.slice().sort((a,b)=>b.at.localeCompare(a.at))[0];b&&restrictedBadge(b)?ctx.modal('Caelum / memory controls','<p>The latest badge uses a disabled memory category. You can review it directly in Profile.</p>'):b?badgeDetail(b.id):ctx.modal('Your next badge','<p>No badge has been earned yet. Your planned exposure is a useful starting point.</p>')}else if(/accomplish.*week/.test(t)){if(!memory.schedule||!memory.metrics){ctx.modal('Caelum / memory controls','<p>Enable Schedule and Health Metrics access for a full weekly review.</p>');return true}weekReview()}else if(/four pillars|all four/.test(t))ctx.modal('Today’s pillars',pillarCard());else if(/boss|closest.*unlock/.test(t)){const list=bossProgress(d(),dayKey()).filter(b=>!b.cleared&&b.id!=='transformation').sort((a,b)=>b.percent-a.percent);ctx.modal('Caelum / next physical milestone',list.map(b=>`<p><strong>${e(b.name)}</strong> · ${b.steps.filter(s=>s.proven).length}/${b.steps.length} evidence steps.<br>Still ahead: ${b.steps.filter(s=>!s.proven).map(s=>e(s.name)).join(', ')}</p>`).join('')+'<p class="legend">XP and cosmetics never count as physical proof.</p>')}else if(/easy xp|minutes|quests/.test(t)){if(!memory.schedule){ctx.modal('Caelum / memory controls','<p>Enable Schedule access for quests that respect protected time.</p>');return true}const requested=+(t.match(/(\d+)\s*minutes/)?.[1]||30),window=availableWindow(d().events),limit=Math.min(requested,window.minutes),choices=d().gameQuests.filter(q=>q.status==='planned'&&q.date<=dayKey()&&q.deadline>=dayKey()&&q.minutes+3<=limit).sort((a,b)=>a.priority-b.priority).slice(0,3);ctx.modal('Caelum / useful next steps',`<p>${e(window.reason)}</p>${choices.map(q=>`<p><strong>${e(q.name)}</strong> · about ${q.minutes} minutes.</p><button data-action="questDetail" data-id="${q.id}">Open quest</button>`).join('')||'<p>No planned quest fits this window. Protect your commitment and save training for later.</p>'}<p class="legend">Complete useful planned work. Repetition, pain and extra relationship time do not produce extra XP.</p>`)}else if(d().gameBadges.some(restrictedBadge)||!memory.routines&&d().rewardLedger.some(r=>r.sourceType==='routine'))ctx.modal('Caelum / memory controls','<p>Some rewards use disabled memory categories. Enable the relevant access for a full reward review, or open your ledger directly in Profile.</p>');else rewards();return true}
 async function handleAction(b){const id=b.dataset.id;switch(b.dataset.action){case 'pillarPlan':planDialog();break;case 'pillarStart':await pillarStart(b.dataset.pillar);break;case 'trophyRoom':trophyRoom();break;case 'badgeDetail':badgeDetail(id);break;case 'bossDetail':bossDetail(id);break;case 'gameRewards':rewards();break;case 'gameWardrobe':wardrobe();break;case 'gameWeek':weekReview();break;case 'questDetail':questDetail(id);break;case 'favoriteBadge':await actions.dispatch('favoriteBadge',{badgeId:id});await ctx.refresh();badgeDetail(id);break;case 'buyCosmetic':await actions.dispatch('purchaseCosmetic',{itemId:id});await ctx.refresh();wardrobe();break;case 'equipGame':await actions.dispatch('equipGameItem',{type:b.dataset.type,itemId:id});await ctx.refresh();wardrobe();break;case 'ackCelebration':await actions.dispatch('acknowledgeCelebration',{id});await ctx.refresh();celebrations();break;case 'gameCelebrations':celebrations();break;case 'stopSafely':await actions.dispatch('stopSafely',{sessionId:id});await ctx.refresh();ctx.showSession(id);break;case 'questCreate':ctx.modal('Personal quest',`<form class="fields">${ctx.field('Quest name','name','text','','required maxlength="100"')}${ctx.field('Minutes','minutes','number',10,'min="1" max="120" required')}${ctx.field('What does completion mean?','description','text','','required maxlength="1000"')}<p class="legend">One modest personal-quest reward per day. No relationship scoring or duration rewards.</p><button class="white">Save quest</button></form>`,async f=>{await actions.dispatch('createPersonalQuest',{name:f.get('name'),minutes:+f.get('minutes'),description:f.get('description')})});break;case 'personalQuestComplete':await actions.dispatch('completePersonalQuest',{questId:id});await ctx.refresh();questDetail(id);break;default:return false}return true}
 function applyCosmetics(){const p=profile();document.documentElement.dataset.orb=p.equipped.orb||'core';document.documentElement.dataset.frame=p.equipped.frame||'';document.documentElement.dataset.stars=p.equipped.stars||'';document.documentElement.dataset.banner=p.equipped.banner||'';document.documentElement.dataset.celebration=ctx.pref().celebrationIntensity||'Minimal'}
 return {todayCard,questPage,profileCard,handleAction,command,maybeCelebrate,applyCosmetics,title:()=>profile().title,level,coins:()=>balances(d()).coins};
}
